FROM node:22-bookworm

ARG CLAUDE_CODE_VERSION=2.1.241

# Install iptables and claude-code
RUN apt-get update && \
    apt-get install -y iptables iproute2 dnsutils sudo && \
    npm install -g @anthropic-ai/claude-code@${CLAUDE_CODE_VERSION} && \
    rm -rf /var/lib/apt/lists/*

# Create non-root user
RUN useradd -m -s /bin/bash claude && \
    echo "claude ALL=(ALL) NOPASSWD: /usr/sbin/iptables, /usr/sbin/ip6tables" >> /etc/sudoers

# Create entrypoint script to setup firewall rules
COPY entrypoint.sh /entrypoint.sh
COPY allowed-domains.txt /etc/allowed-domains.txt
COPY server.js /opt/claudebox/server.js
RUN chmod 755 /entrypoint.sh

WORKDIR /workspace
RUN chown claude:claude /workspace

USER claude

EXPOSE 3000

ENTRYPOINT ["/bin/bash", "/entrypoint.sh"]
CMD ["node", "/opt/claudebox/server.js"]
#!/bin/bash

# ---------------------------------------------------------------------------
# Auth: resolve CLAUDE_CODE_OAUTH_TOKEN
#   1. Already set via env_file / environment  → use it (macOS path)
#   2. Mounted credentials file exists          → extract from it (Linux path)
#   3. Neither                                  → fail with instructions
# ---------------------------------------------------------------------------
CREDENTIALS_MOUNT="/run/claude-credentials"

if [ -z "${CLAUDE_CODE_OAUTH_TOKEN:-}" ]; then
    if [ -f "$CREDENTIALS_MOUNT" ]; then
        echo "Reading OAuth token from mounted credentials file..." >&2
        CLAUDE_CODE_OAUTH_TOKEN=$(node -e "
            const creds = JSON.parse(require('fs').readFileSync('$CREDENTIALS_MOUNT', 'utf8'));
            const token = creds.claudeAiOauth && creds.claudeAiOauth.accessToken;
            if (!token) { console.error('No accessToken found in credentials file'); process.exit(1); }
            process.stdout.write(token);
        ") || { echo "ERROR: Failed to parse credentials file." >&2; exit 1; }
        export CLAUDE_CODE_OAUTH_TOKEN
    else
        echo "ERROR: No authentication found." >&2
        echo "" >&2
        echo "  Linux users:  credentials are mounted automatically if you have" >&2
        echo "                run 'claude login' on this machine." >&2
        echo "" >&2
        echo "  macOS users:  run ./setup-auth.sh once (Keychain can't be mounted)." >&2
        exit 1
    fi
fi

ALLOWED_DOMAINS_FILE="/etc/allowed-domains.txt"

# Setup firewall rules with sudo (container must have NET_ADMIN capability)
echo "Setting up firewall rules..." >&2

# Allow loopback
sudo iptables -A OUTPUT -o lo -j ACCEPT

# Allow established connections
sudo iptables -A OUTPUT -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT

# Allow DNS to all configured nameservers and Docker gateway
for ns in $(awk '/^nameserver/ {print $2}' /etc/resolv.conf); do
    echo "Allowing DNS to nameserver: $ns" >&2
    sudo iptables -A OUTPUT -d "$ns" -p udp --dport 53 -j ACCEPT
    sudo iptables -A OUTPUT -d "$ns" -p tcp --dport 53 -j ACCEPT
done
GATEWAY_IP=$(ip route | grep default | awk '{print $3}')
if [ -n "$GATEWAY_IP" ]; then
    echo "Allowing DNS to Docker gateway: $GATEWAY_IP" >&2
    sudo iptables -A OUTPUT -d "$GATEWAY_IP" -p udp --dport 53 -j ACCEPT
    sudo iptables -A OUTPUT -d "$GATEWAY_IP" -p tcp --dport 53 -j ACCEPT
fi
# Temporary: allow DNS to external resolver for domain resolution (removed after)
sudo iptables -A OUTPUT -p udp --dport 53 -j ACCEPT

# Resolve and allow domains from the allowlist
if [ -f "$ALLOWED_DOMAINS_FILE" ]; then
    while IFS= read -r domain || [ -n "$domain" ]; do
        domain=$(echo "$domain" | xargs)
        [[ -z "$domain" || "$domain" == \#* ]] && continue
        echo "Resolving $domain..." >&2
        IPS=$(dig +short "$domain" @8.8.8.8 | grep -E '^[0-9.]+$')
        for ip in $IPS; do
            echo "  Allowing $domain -> $ip" >&2
            sudo iptables -A OUTPUT -d "$ip" -j ACCEPT
        done
    done < "$ALLOWED_DOMAINS_FILE"
else
    echo "WARNING: $ALLOWED_DOMAINS_FILE not found. No domains will be allowed." >&2
fi

# Remove temporary DNS rule
sudo iptables -D OUTPUT -p udp --dport 53 -j ACCEPT

# Drop all other outbound traffic (IPv4 + IPv6)
sudo iptables -A OUTPUT -j DROP
sudo ip6tables -A OUTPUT -o lo -j ACCEPT
sudo ip6tables -A OUTPUT -j DROP

echo "Firewall rules applied. Only allowlisted domains and Docker host are reachable." >&2

# Execute the command as claude user
exec "$@"
const http = require("http");
const { spawn } = require("child_process");
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const PORT = parseInt(process.env.PORT || "3000", 10);
const MAX_CONCURRENT = parseInt(process.env.MAX_CONCURRENT || "4", 10);
const OPENAI_COMPAT = process.env.OPENAI_COMPAT === "1";
const CLAUDEBOX_API_KEY = process.env.CLAUDEBOX_API_KEY || "";

let activeRequests = 0;

// ---------------------------------------------------------------------------
// Logging
// ---------------------------------------------------------------------------

function log(level, msg, meta = {}) {
  const entry = { ts: new Date().toISOString(), level, msg, ...meta };
  process.stderr.write(JSON.stringify(entry) + "\n");
}

// ---------------------------------------------------------------------------
// HTTP helpers
// ---------------------------------------------------------------------------

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => (data += chunk));
    req.on("end", () => resolve(data));
    req.on("error", reject);
  });
}

function sendJSON(res, status, body) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
}

// ---------------------------------------------------------------------------
// Claude runner
// ---------------------------------------------------------------------------

function buildClaudeArgs(prompt, options = {}) {
  const args = [
    "-p",
    "--output-format",
    "json",
    "--dangerously-skip-permissions",
    "--no-session-persistence",
  ];

  if (options.model) args.push("--model", options.model);
  if (options.maxTurns) args.push("--max-turns", String(options.maxTurns));
  if (options.maxBudgetUsd)
    args.push("--max-budget-usd", String(options.maxBudgetUsd));
  if (options.systemPrompt)
    args.push("--system-prompt", options.systemPrompt);
  if (options.appendSystemPrompt)
    args.push("--append-system-prompt", options.appendSystemPrompt);
  if (options.jsonSchema)
    args.push("--json-schema", options.jsonSchema);
  if (options.allowedTools)
    args.push("--allowedTools", ...options.allowedTools);

  args.push("--", prompt);
  return args;
}

function runClaude(prompt, options = {}) {
  return new Promise((resolve, reject) => {
    const args = buildClaudeArgs(prompt, options);

    log("info", "spawning claude", { prompt: prompt.slice(0, 100) });

    const proc = spawn("claude", args, {
      stdio: ["inherit", "pipe", "pipe"],
      cwd: options.cwd || "/workspace",
    });

    let stdout = "";
    let stderr = "";
    proc.stdout.on("data", (d) => (stdout += d));
    proc.stderr.on("data", (d) => (stderr += d));

    proc.on("error", (err) => reject(err));
    proc.on("close", (code) => {
      if (code !== 0) {
        log("error", "claude exited with error", { code, stderr });
        reject(new Error(stderr || `claude exited with code ${code}`));
      } else {
        resolve(stdout);
      }
    });
  });
}

// ---------------------------------------------------------------------------
// OpenAI Compatibility Layer
// ---------------------------------------------------------------------------

const TMP_DIR = process.env.CLAUDEBOX_TMP_DIR || "/workspace/.tmp";

const MIME_TO_EXT = {
  "image/jpeg": "jpg",
  "image/png": "png",
  "image/gif": "gif",
  "image/webp": "webp",
  "image/bmp": "bmp",
  "image/tiff": "tiff",
};

function checkApiKey(req) {
  if (!CLAUDEBOX_API_KEY) return true;
  const auth = req.headers.authorization || "";
  return auth === `Bearer ${CLAUDEBOX_API_KEY}`;
}

function ensureTmpDir() {
  if (!fs.existsSync(TMP_DIR)) {
    fs.mkdirSync(TMP_DIR, { recursive: true });
  }
}

function cleanupTmpFiles(files) {
  for (const f of files) {
    try {
      fs.unlinkSync(f);
    } catch (err) {
      log("warn", "failed to cleanup temp file", { file: f, error: err.message });
    }
  }
}

function processContentParts(content) {
  const textParts = [];
  const tmpFiles = [];

  try {
    for (const part of content) {
      if (part.type === "text") {
        textParts.push(part.text);
      } else if (part.type === "image_url") {
        const url = part.image_url?.url || "";
        const match = url.match(/^data:(image\/[^;]+);base64,(.+)$/s);
        if (!match) {
          throw new Error(
            "Only data: base64 image URIs are supported. External image URLs are not accepted."
          );
        }
        const mimeType = match[1];
        const base64Data = match[2];
        const ext = MIME_TO_EXT[mimeType] || mimeType.split("/")[1];
        const filename = `img-${crypto.randomUUID()}.${ext}`;
        const filepath = path.join(TMP_DIR, filename);

        ensureTmpDir();
        fs.writeFileSync(filepath, Buffer.from(base64Data, "base64"));
        tmpFiles.push(filepath);

        textParts.push(
          `[Attached image: ${filepath} — use the Read tool to view this file]`
        );
      }
    }
  } catch (err) {
    cleanupTmpFiles(tmpFiles);
    throw err;
  }

  return { text: textParts.join("\n"), tmpFiles };
}

function extractMessageText(content) {
  if (typeof content === "string") return { text: content, tmpFiles: [] };
  if (Array.isArray(content)) return processContentParts(content);
  return { text: "", tmpFiles: [] };
}

function parseOpenAIRequest(body) {
  const messages = body.messages || [];
  const systemParts = [];
  const conversationMessages = [];
  const allTmpFiles = [];

  try {
    for (const msg of messages) {
      if (msg.role === "system") {
        const { text } = extractMessageText(msg.content);
        if (text) systemParts.push(text);
      } else {
        const { text, tmpFiles } = extractMessageText(msg.content);
        allTmpFiles.push(...tmpFiles);
        conversationMessages.push({ role: msg.role, text });
      }
    }
  } catch (err) {
    cleanupTmpFiles(allTmpFiles);
    throw err;
  }

  let prompt;
  if (conversationMessages.length === 0) {
    prompt = "";
  } else if (conversationMessages.length === 1) {
    prompt = conversationMessages[0].text;
  } else {
    const history = conversationMessages.slice(0, -1);
    const last = conversationMessages[conversationMessages.length - 1];

    const historyLines = history.map((m) => {
      const role = m.role === "assistant" ? "Assistant" : "User";
      return `${role}: ${m.text}`;
    });

    prompt = `[conversation history]\n${historyLines.join("\n")}\n[current request]\n${last.text}`;
  }

  return {
    prompt,
    systemPrompt: systemParts.length > 0 ? systemParts.join("\n\n") : null,
    model: body.model || null,
    responseFormat: body.response_format || null,
    tmpFiles: allTmpFiles,
  };
}

function getJsonSchemaString(responseFormat) {
  if (!responseFormat) return null;

  let schema;
  if (responseFormat.type === "json_schema") {
    schema = responseFormat.json_schema?.schema || responseFormat.schema;
    if (!schema) return null;
  } else if (responseFormat.type === "json_object") {
    schema = { type: "object" };
  } else {
    return null;
  }

  return JSON.stringify(schema);
}

function parseClaudeOutput(raw) {
  try {
    const parsed = JSON.parse(raw);
    let text;
    if (parsed.structured_output !== undefined) {
      text = JSON.stringify(parsed.structured_output);
    } else {
      text = parsed.result || raw;
    }
    return { text, usage: parsed.usage || {} };
  } catch {
    return { text: raw, usage: {} };
  }
}

function toOpenAIResponse(resultText, model, usage) {
  return {
    id: `chatcmpl-${crypto.randomUUID()}`,
    object: "chat.completion",
    created: Math.floor(Date.now() / 1000),
    model: model || "claude-sonnet-4-6",
    choices: [
      {
        index: 0,
        message: { role: "assistant", content: resultText },
        finish_reason: "stop",
      },
    ],
    usage: {
      prompt_tokens: usage.input_tokens || 0,
      completion_tokens: usage.output_tokens || 0,
      total_tokens: (usage.input_tokens || 0) + (usage.output_tokens || 0),
    },
  };
}

async function handleChatCompletions(req, res) {
  if (!checkApiKey(req)) {
    sendJSON(res, 401, {
      error: { message: "Invalid API key", type: "authentication_error" },
    });
    return;
  }

  if (activeRequests >= MAX_CONCURRENT) {
    log("warn", "rejected openai request, at capacity", { activeRequests });
    sendJSON(res, 429, {
      error: { message: "Too many concurrent requests", type: "rate_limit_error" },
    });
    return;
  }

  activeRequests++;
  let parsed;
  try {
    const rawBody = await readBody(req);
    let body;
    try {
      body = JSON.parse(rawBody);
    } catch {
      sendJSON(res, 400, {
        error: { message: "Invalid JSON body", type: "invalid_request_error" },
      });
      return;
    }

    if (!body.messages || !Array.isArray(body.messages) || body.messages.length === 0) {
      sendJSON(res, 400, {
        error: { message: "Missing or empty 'messages' array", type: "invalid_request_error" },
      });
      return;
    }

    try {
      parsed = parseOpenAIRequest(body);
    } catch (err) {
      sendJSON(res, 400, {
        error: { message: err.message, type: "invalid_request_error" },
      });
      return;
    }

    if (!parsed.prompt) {
      sendJSON(res, 400, {
        error: { message: "No user message content found", type: "invalid_request_error" },
      });
      return;
    }

    const options = {};
    if (parsed.systemPrompt) options.systemPrompt = parsed.systemPrompt;
    if (parsed.model) options.model = parsed.model;

    const jsonSchema = getJsonSchemaString(parsed.responseFormat);
    if (jsonSchema) options.jsonSchema = jsonSchema;

    log("info", "openai compat: spawning claude", { model: parsed.model, hasSchema: !!jsonSchema });
    const raw = await runClaude(parsed.prompt, options);
    const { text: resultText, usage } = parseClaudeOutput(raw);

    sendJSON(res, 200, toOpenAIResponse(resultText, parsed.model, usage));
  } catch (err) {
    log("error", "openai compat error", { error: err.message });
    sendJSON(res, 500, {
      error: { message: err.message, type: "server_error" },
    });
  } finally {
    if (parsed?.tmpFiles?.length > 0) {
      cleanupTmpFiles(parsed.tmpFiles);
    }
    activeRequests--;
  }
}

function handleModels(req, res) {
  if (!checkApiKey(req)) {
    sendJSON(res, 401, {
      error: { message: "Invalid API key", type: "authentication_error" },
    });
    return;
  }

  const models = [
    "claude-sonnet-4-6",
    "claude-opus-4-6",
    "claude-haiku-4-5-20251001",
    "sonnet",
    "opus",
    "haiku",
  ].map((id) => ({
    id,
    object: "model",
    created: 1711100000,
    owned_by: "anthropic",
  }));

  sendJSON(res, 200, { object: "list", data: models });
}

// ---------------------------------------------------------------------------
// Server
// ---------------------------------------------------------------------------

const server = http.createServer(async (req, res) => {
  // --- Health check ---
  if (req.method === "GET" && req.url === "/health") {
    sendJSON(res, 200, { status: "ok", activeRequests });
    return;
  }

  // --- Custom prompt API ---
  if (req.method === "POST" && req.url === "/prompt") {
    if (activeRequests >= MAX_CONCURRENT) {
      log("warn", "rejected request, at capacity", { activeRequests });
      sendJSON(res, 429, { error: "Too many concurrent requests" });
      return;
    }

    activeRequests++;
    try {
      const raw = await readBody(req);
      let body;
      try {
        body = JSON.parse(raw);
      } catch {
        sendJSON(res, 400, { error: "Invalid JSON body" });
        return;
      }

      if (!body.prompt) {
        sendJSON(res, 400, { error: "Missing 'prompt' field" });
        return;
      }

      const result = await runClaude(body.prompt, body.options || {});
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(result);
    } catch (err) {
      sendJSON(res, 500, { error: err.message });
    } finally {
      activeRequests--;
    }
    return;
  }

  // --- OpenAI-compatible endpoints ---
  if (OPENAI_COMPAT) {
    if (req.method === "POST" && req.url === "/v1/chat/completions") {
      await handleChatCompletions(req, res);
      return;
    }

    if (req.method === "GET" && req.url === "/v1/models") {
      handleModels(req, res);
      return;
    }
  }

  // --- 404 ---
  const routes = ["POST /prompt", "GET /health"];
  if (OPENAI_COMPAT) {
    routes.push("POST /v1/chat/completions", "GET /v1/models");
  }
  sendJSON(res, 404, { error: `Not found. Available: ${routes.join(", ")}` });
});

if (require.main === module) {
  server.listen(PORT, "0.0.0.0", () => {
    log("info", `claudebox server listening on port ${PORT}`, {
      maxConcurrent: MAX_CONCURRENT,
      openaiCompat: OPENAI_COMPAT,
    });
  });
}

module.exports = { buildClaudeArgs };
const assert = require("node:assert/strict");
const test = require("node:test");

const { buildClaudeArgs } = require("../server");

test("separates allowedTools values from the positional prompt", () => {
  const args = buildClaudeArgs("explain DNS", {
    allowedTools: ["Read", "Bash(git status:*)"],
  });

  assert.deepEqual(args.slice(-5), [
    "--allowedTools",
    "Read",
    "Bash(git status:*)",
    "--",
    "explain DNS",
  ]);
});

test("treats a leading-dash prompt as positional input", () => {
  const args = buildClaudeArgs("--help");

  assert.deepEqual(args.slice(-2), ["--", "--help"]);
});
services:
  claudebox:
    image: ghcr.io/armanjr/claudebox:latest
    build:
      context: .
      dockerfile: Dockerfile
    cap_add:
      - NET_ADMIN
    ports:
      - "${CLAUDEBOX_PORT:-3000}:3000"
    env_file:
