"use strict";
// Converts Claude Code `--output-format stream-json --verbose --include-partial-messages`
// lines into the NORMALIZED RunEvents defined in server/src/shared/protocol.ts.
// See PROTOCOL.md for the full raw -> normalized mapping table.

const TOOL_RESULT_MAX_BYTES = 20 * 1024;

function truncateBytes(str, maxBytes = TOOL_RESULT_MAX_BYTES) {
  if (typeof str !== "string") str = String(str ?? "");
  const buf = Buffer.from(str, "utf8");
  if (buf.length <= maxBytes) return str;
  let cut = buf.subarray(0, maxBytes).toString("utf8");
  cut = cut.replace(/�+$/, "");
  return `${cut}\n…[truncated ${buf.length - maxBytes} bytes]`;
}

function stringifyToolContent(content) {
  if (content == null) return "";
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    return content
      .map((b) => {
        if (b == null) return "";
        if (typeof b === "string") return b;
        if (b.type === "text") return b.text ?? "";
        if (b.type === "image") return "[image]";
        if (b.type === "document") return "[document]";
        if (b.type === "tool_reference") return `[tool: ${b.tool_name ?? b.name ?? "?"}]`;
        return JSON.stringify(b);
      })
      .join("\n");
  }
  if (typeof content === "object" && content.type === "text") return content.text ?? "";
  return JSON.stringify(content);
}

function toUsage(u) {
  u = u || {};
  return {
    inputTokens: Number(u.input_tokens) || 0,
    outputTokens: Number(u.output_tokens) || 0,
    cacheReadTokens: Number(u.cache_read_input_tokens) || 0,
    cacheWriteTokens: Number(u.cache_creation_input_tokens) || 0,
  };
}

const USAGE_KEYS = ["inputTokens", "outputTokens", "cacheReadTokens", "cacheWriteTokens"];
const TODO_STATUSES = new Set(["pending", "in_progress", "completed"]);

class Normalizer {
  /** @param {(type: string, data: object) => void} emit */
  constructor(emit) {
    this._emit = emit;
    this.sessionId = null;
    this.model = null;
    this.initEmitted = false;
    this.sawResult = false;
    this.errorEmitted = false;
    this.lastResult = null;

    this.streamed = new Set(); // message ids that arrived as stream_event partials
    this.curMsgId = null;
    this.openBlocks = new Map(); // index -> "thinking" | "text" | other
    this.pendingUsage = new Map(); // streamed message id -> raw usage (accumulated)
    this.emittedUsage = new Map(); // message id -> normalized usage already emitted
    this.emittedToolUse = new Set();
    this.toolInfo = new Map(); // tool_use id -> {name, input, parentId}
    this.tasks = []; // TaskCreate/TaskUpdate-derived todo list (main thread)
    this._buf = "";
  }

  emit(type, data) {
    if (type === "error") this.errorEmitted = true;
    this._emit(type, data);
  }

  /** Feed raw stdout chunk(s); splits into lines. */
  write(chunk) {
    this._buf += chunk;
    let nl;
    while ((nl = this._buf.indexOf("\n")) !== -1) {
      const line = this._buf.slice(0, nl);
      this._buf = this._buf.slice(nl + 1);
      this.feedLine(line);
    }
  }

  flushBuffer() {
    if (this._buf.trim()) this.feedLine(this._buf);
    this._buf = "";
  }

  feedLine(line) {
    line = line.trim();
    if (!line) return;
    let obj;
    try {
      obj = JSON.parse(line);
    } catch {
      return; // non-JSON noise is never forwarded
    }
    if (obj && typeof obj === "object") this.handle(obj);
  }

  handle(obj) {
    try {
      switch (obj.type) {
        case "system":
          return this._system(obj);
        case "stream_event":
          return this._stream(obj);
        case "assistant":
          return this._assistant(obj);
        case "user":
          return this._user(obj);
        case "result":
          return this._result(obj);
        case "rate_limit_event":
          return this.emit("rate_limit", { ...(obj.rate_limit_info || {}) });
        default:
          return; // keep_alive, tool_progress, prompt_suggestion, ... ignored
      }
    } catch (err) {
      // Never let a malformed line kill the run stream.
      this._emit("__internal_error", { message: err.message });
    }
  }

  _system(obj) {
    if (obj.subtype === "init") {
      if (obj.session_id) this.sessionId = obj.session_id;
      if (obj.model) this.model = obj.model;
      if (this.initEmitted) return;
      this.initEmitted = true;
      this.emit("init", {
        sessionId: obj.session_id || "",
        model: obj.model || "",
        tools: Array.isArray(obj.tools) ? obj.tools : [],
        cwd: obj.cwd || "",
        permissionMode: obj.permissionMode,
        claudeCodeVersion: obj.claude_code_version,
      });
    }
    // status / compact_boundary / hook_* / task_* subtypes are not part of the protocol.
  }

  _stream(obj) {
    if (obj.parent_tool_use_id) return; // subagent partials are not streamed as main text
    const ev = obj.event || {};
    switch (ev.type) {
      case "message_start": {
        const id = ev.message?.id || `anon-${Date.now()}-${Math.random()}`;
        this.curMsgId = id;
        this.streamed.add(id);
        this.openBlocks.clear();
        this.pendingUsage.set(id, { ...(ev.message?.usage || {}) });
        return;
      }
      case "content_block_start": {
        const cb = ev.content_block || {};
        this.openBlocks.set(ev.index, cb.type);
        if (cb.type === "text" && cb.text) this.emit("text", { delta: cb.text });
        if (cb.type === "thinking" && cb.thinking) this.emit("thinking", { delta: cb.thinking });
        return;
      }
      case "content_block_delta": {
        const d = ev.delta || {};
        if (d.type === "text_delta" && d.text) this.emit("text", { delta: d.text });
        else if (d.type === "thinking_delta" && d.thinking) this.emit("thinking", { delta: d.thinking });
        return; // input_json_delta / signature_delta / citations_delta: tool_use is emitted from the full assistant message
      }
      case "content_block_stop": {
        const kind = this.openBlocks.get(ev.index);
        this.openBlocks.delete(ev.index);
        if (kind === "text" || kind === "thinking") this.emit("block_end", { kind });
        return;
      }
      case "message_delta": {
        if (this.curMsgId && ev.usage) {
          const cur = this.pendingUsage.get(this.curMsgId) || {};
          for (const [k, v] of Object.entries(ev.usage)) if (v != null) cur[k] = v;
          this.pendingUsage.set(this.curMsgId, cur);
        }
        return;
      }
      case "message_stop": {
        this._closeOpenBlocks();
        if (this.curMsgId) this._flushPendingUsage(this.curMsgId);
        this.curMsgId = null;
        return;
      }
      default:
        return; // ping etc.
    }
  }

  _closeOpenBlocks() {
    for (const kind of this.openBlocks.values()) {
      if (kind === "text" || kind === "thinking") this.emit("block_end", { kind });
    }
    this.openBlocks.clear();
  }

  _flushPendingUsage(id) {
    const raw = this.pendingUsage.get(id);
    if (!raw) return;
    this.pendingUsage.delete(id);
    this._emitUsageDelta(id, toUsage(raw), null);
  }

  _emitUsageDelta(id, usage, parentId) {
    const prev = this.emittedUsage.get(id) || { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
    const delta = {};
    let any = false;
    const next = { ...prev };
    for (const k of USAGE_KEYS) {
      const d = Math.max(0, (usage[k] || 0) - prev[k]);
      delta[k] = d;
      next[k] = Math.max(prev[k], usage[k] || 0);
      if (d > 0) any = true;
    }
    this.emittedUsage.set(id, next);
    if (!any) return;
    const data = { ...delta };
    if (parentId) data.parentId = parentId;
    this.emit("usage", data);
  }

  _assistant(obj) {
    const msg = obj.message || {};
    const id = msg.id || null;
    const parentId = obj.parent_tool_use_id || null;
    const content = Array.isArray(msg.content) ? msg.content : [];

    if (obj.error || obj.is_api_error_message) {
      const text = content.filter((b) => b && b.type === "text").map((b) => b.text).join("\n");
      this.emit("error", { message: text || String(obj.error || "API error"), code: obj.error || "api_error" });
      return;
    }

    const streamed = id != null && this.streamed.has(id);
    for (const block of content) {
      if (!block || typeof block !== "object") continue;
