"use strict";
// Converts Claude Code `--output-format stream-json --verbose --include-partial-messages`
// lines into the NORMALIZED RunEvents defined in server/src/shared/protocol.ts.
// See PROTOCOL.md for the full raw -> normalized mapping table.

const TOOL_RESULT_MAX_BYTES = 20 * 1024;

function truncateBytes(str, maxBytes = TOOL_RESULT_MAX_BYTES) {
  if (typeof str !== "string") str = String(str ?? "");
  const buf = Buffer.from(str, "utf8");
  if (buf.length <= maxBytes) return str;
  let cut = buf.subarray(0, maxBytes).toString("utf8");
  cut = cut.replace(/\uFFFD+$/, "");
  return `${cut}\n…[truncated ${buf.length - maxBytes} bytes]`;
}

function stringifyToolContent(content) {
  if (content == null) return "";
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    return content
      .map((b) => {
        if (b == null) return "";
        if (typeof b === "string") return b;
        if (b.type === "text") return b.text ?? "";
        if (b.type === "image") return "[image]";
        if (b.type === "document") return "[document]";
        if (b.type === "tool_reference") return `[tool: ${b.tool_name ?? b.name ?? "?"}]`;
        return JSON.stringify(b);
      })
      .join("\n");
  }
  if (typeof content === "object" && content.type === "text") return content.text ?? "";
  return JSON.stringify(content);
}

function toUsage(u) {
  u = u || {};
  return {
    inputTokens: Number(u.input_tokens) || 0,
    outputTokens: Number(u.output_tokens) || 0,
    cacheReadTokens: Number(u.cache_read_input_tokens) || 0,
    cacheWriteTokens: Number(u.cache_creation_input_tokens) || 0,
  };
}

const USAGE_KEYS = ["inputTokens", "outputTokens", "cacheReadTokens", "cacheWriteTokens"];
const TODO_STATUSES = new Set(["pending", "in_progress", "completed"]);

class Normalizer {
  /** @param {(type: string, data: object) => void} emit */
  constructor(emit) {
    this._emit = emit;
    this.sessionId = null;
    this.model = null;
    this.initEmitted = false;
    this.sawResult = false;
    this.errorEmitted = false;
    this.lastResult = null;

    this.streamed = new Set(); // message ids that arrived as stream_event partials
    this.curMsgId = null;
    this.openBlocks = new Map(); // index -> "thinking" | "text" | other
    this.pendingUsage = new Map(); // streamed message id -> raw usage (accumulated)
    this.emittedUsage = new Map(); // message id -> normalized usage already emitted
    this.emittedToolUse = new Set();
    this.toolInfo = new Map(); // tool_use id -> {name, input, parentId}
    this.tasks = []; // TaskCreate/TaskUpdate-derived todo list (main thread)
    this._buf = "";
  }

  emit(type, data) {
    if (type === "error") this.errorEmitted = true;
    this._emit(type, data);
  }

  /** Feed raw stdout chunk(s); splits into lines. */
  write(chunk) {
    this._buf += chunk;
    let nl;
    while ((nl = this._buf.indexOf("\n")) !== -1) {
      const line = this._buf.slice(0, nl);
      this._buf = this._buf.slice(nl + 1);
      this.feedLine(line);
    }
  }

  flushBuffer() {
    if (this._buf.trim()) this.feedLine(this._buf);
    this._buf = "";
  }

  feedLine(line) {
    line = line.trim();
    if (!line) return;
    let obj;
    try {
      obj = JSON.parse(line);
    } catch {
      return; // non-JSON noise is never forwarded
