    const cwd = path.join(c.projectsDir, body.projectSlug);
    const attachments = [];
    if (body.attachments != null) {
      if (!Array.isArray(body.attachments) || body.attachments.length > 100) return { error: "Invalid attachments" };
      for (const a of body.attachments) {
        if (typeof a !== "string" || /[\r\n\0]/.test(a)) return { error: "Invalid attachment path" };
        const resolved = path.resolve(a);
        if (!isInside(resolved, c.uploadsDir) && !isInside(resolved, cwd))
          return { error: `Attachment must be under ${c.uploadsDir} or the project dir: ${a}` };
        attachments.push(resolved);
      }
    }
    if (!body.prompt.trim() && !attachments.length) return { error: "Empty prompt" };

    return {
      opts: {
        runId, prompt: body.prompt, projectSlug: body.projectSlug, cwd, sessionId, model, mode, thinking,
        effort, attachments, appendSystemPrompt, maxTurns, previewPort, authToken,
        fullPrompt: buildPrompt(body.prompt, attachments),
      },
    };
  }

  get(runId) {
    return this.runs.get(runId) || null;
  }

  create(opts) {
    if (this.runs.has(opts.runId)) {
      const err = new Error(`Run ${opts.runId} already exists`);
      err.code = "RUN_EXISTS";
      throw err;
    }
    fs.mkdirSync(opts.cwd, { recursive: true });
    const run = {
      runId: opts.runId,
      projectSlug: opts.projectSlug,
      cwd: opts.cwd,
      mode: opts.mode,
      model: opts.model,
      opts,
      status: "queued",
      createdAt: Date.now(),
      startedAt: null,
      endedAt: null,
      exitCode: null,
      sessionId: opts.sessionId || null,
      events: [],
      nextSeq: 1,
      subscribers: new Set(),
      proc: null,
      pid: null,
      aborted: false,
      stderrTail: "",
      finished: false,
    };
    this.runs.set(run.runId, run);
    this.queue.push(run);
    this.config.log("info", "run queued", { runId: run.runId, projectSlug: run.projectSlug, mode: run.mode, model: run.model });
    this._pump();
    return run;
  }

  _pump() {
    while (this.running < this.config.maxConcurrent && this.queue.length) {
      const run = this.queue.shift();
      if (run.status !== "queued") continue;
      this._start(run);
    }
  }

  _push(run, type, data) {
    if (type === "__internal_error") {
      this.config.log("warn", "normalizer error", { runId: run.runId, ...data });
      return;
    }
    if (type === "init" && data.sessionId) run.sessionId = data.sessionId;
    if (type === "result" && data.sessionId) run.sessionId = data.sessionId;
    const ev = { seq: run.nextSeq++, type, data };
    run.events.push(ev);
    const max = this.config.maxEventsPerRun;
    if (run.events.length > max * 1.1) run.events.splice(0, run.events.length - max);
    const frame = sseFrame(ev);
    for (const sub of run.subscribers) {
      try {
        sub.res.write(frame);
      } catch {
        /* ignore */
      }
    }
  }

  _start(run) {
    const c = this.config;
    const opts = run.opts;
    const features = c.features() || {};
    const args = buildRunArgs(opts, features, c);
    const env = buildChildEnv(c.env, opts);
    const norm = new Normalizer((type, data) => this._push(run, type, data));
    run.normalizer = norm;
    run.status = "running";
    run.startedAt = Date.now();
    this.running++;

    let proc;
    try {
      proc = spawn(c.claudeBin, args, { cwd: run.cwd, env, stdio: ["ignore", "pipe", "pipe"], detached: true });
    } catch (err) {
      this._finish(run, { exitCode: null, spawnError: err });
      return;
    }
    run.proc = proc;
    run.pid = proc.pid;
    c.log("info", "run started", { runId: run.runId, pid: proc.pid, args: args.slice(0, -1) });

    proc.stdout.setEncoding("utf8");
    proc.stdout.on("data", (d) => norm.write(d));
    proc.stderr.setEncoding("utf8");
    proc.stderr.on("data", (d) => {
      run.stderrTail = (run.stderrTail + d).slice(-8192);
    });

    let exitInfo = null;
    let closeTimer = null;
    proc.on("error", (err) => {
      c.log("error", "run spawn error", { runId: run.runId, error: err.message });
      this._finish(run, { exitCode: null, spawnError: err });
    });
    proc.on("exit", (code, signal) => {
      exitInfo = { code, signal };
      // stdout may be held open by background children; don't wait forever.
      closeTimer = setTimeout(() => this._finish(run, { exitCode: code, signal }), 2000);
    });
    proc.on("close", (code, signal) => {
      if (closeTimer) clearTimeout(closeTimer);
      const info = exitInfo || { code, signal };
      this._finish(run, { exitCode: info.code, signal: info.signal });
    });
  }

  _finish(run, { exitCode, signal, spawnError }) {
    if (run.finished) return;
    run.finished = true;
    if (run.killTimer) clearTimeout(run.killTimer);
    const norm = run.normalizer || new Normalizer((t, d) => this._push(run, t, d));
    norm.finish({ exitCode, aborted: run.aborted, stderr: run.stderrTail, spawnError });
    run.exitCode = exitCode ?? null;
    run.endedAt = Date.now();
    if (run.aborted) run.status = "aborted";
    else if (spawnError || norm.errorEmitted || (norm.lastResult && norm.lastResult.isError) || (!norm.sawResult && exitCode !== 0))
      run.status = "error";
    else run.status = "done";
    const done = { exitCode: run.exitCode };
    if (signal) done.signal = signal;
    if (run.aborted) done.aborted = true;
    this._push(run, "done", done);
    this.config.log("info", "run finished", { runId: run.runId, status: run.status, exitCode, signal, ms: run.endedAt - (run.startedAt || run.createdAt) });
    for (const sub of run.subscribers) this._endSub(run, sub);
    run.proc = null;
    if (run.startedAt) {
      this.running--;
      this._pump();
    }
  }

  _kill(run, sig) {
    if (!run.pid) return;
    try {
      process.kill(-run.pid, sig);
    } catch {
      try {
        process.kill(run.pid, sig);
      } catch {
        /* gone */
      }
    }
  }

  abort(runId) {
    const run = this.runs.get(runId);
    if (!run) return { found: false };
    if (TERMINAL.has(run.status)) return { found: true, status: run.status, alreadyFinished: true };
    run.aborted = true;
    if (run.status === "queued") {
      this.queue = this.queue.filter((r) => r !== run);
      this._finish(run, { exitCode: null });
      return { found: true, status: run.status };
    }
    this.config.log("info", "aborting run", { runId, pid: run.pid });
    this._kill(run, "SIGTERM");
    run.killTimer = setTimeout(() => this._kill(run, "SIGKILL"), this.config.killGraceMs);
    run.killTimer.unref?.();
    return { found: true, status: "aborting" };
  }

  /** Attach an SSE response. Replays events with seq >= fromSeq, then follows live. */
  subscribe(run, req, res, fromSeq = 1) {
    res.writeHead(200, {
      "Content-Type": "text/event-stream; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
      "X-Accel-Buffering": "no",
      "X-Run-Id": run.runId,
      "X-Run-Status": run.status,
    });
    res.write(`retry: 2000\n\n`);
    if (res.socket) res.socket.setNoDelay?.(true);
    for (const ev of run.events) if (ev.seq >= fromSeq) res.write(sseFrame(ev));
    if (run.finished) {
      res.end();
      return;
    }
    const sub = { res, hb: null };
    sub.hb = setInterval(() => {
      try {
        res.write(`: ping ${Date.now()}\n\n`);
      } catch {
        /* ignore */
      }
    }, this.config.heartbeatMs);
    sub.hb.unref?.();
    run.subscribers.add(sub);
    const detach = () => {
      clearInterval(sub.hb);
      run.subscribers.delete(sub);
    };
    // Client disconnect does NOT abort the run (the app may reattach via /v2/run/:id/events).
    req.on("close", detach);
    res.on("close", detach);
  }

  _endSub(run, sub) {
    clearInterval(sub.hb);
    run.subscribers.delete(sub);
    try {
      sub.res.end();
    } catch {
      /* ignore */
    }
  }

  info(run) {
    return {
      runId: run.runId,
      projectSlug: run.projectSlug,
      status: run.status,
      mode: run.mode,
      model: run.model,
      sessionId: run.sessionId,
      pid: run.pid,
      createdAt: run.createdAt,
      startedAt: run.startedAt,
      endedAt: run.endedAt,
      exitCode: run.exitCode,
      lastSeq: run.nextSeq - 1,
      firstSeq: run.events.length ? run.events[0].seq : null,
      subscribers: run.subscribers.size,
    };
  }

  list({ all = false } = {}) {
    const out = [];
    for (const run of this.runs.values()) if (all || !TERMINAL.has(run.status)) out.push(this.info(run));
    return out;
  }

  stats() {
    return { running: this.running, queued: this.queue.length, retained: this.runs.size };
  }

  gc(now = Date.now()) {
    for (const [id, run] of this.runs) {
      if (run.finished && run.endedAt && now - run.endedAt > this.config.retentionMs && run.subscribers.size === 0) {
        this.runs.delete(id);
      }
    }
  }
}

function sseFrame(ev) {
  return `id: ${ev.seq}\nevent: ${ev.type}\ndata: ${JSON.stringify(ev.data)}\n\n`;
}

module.exports = { RunManager, buildRunArgs, buildPrompt, buildChildEnv, sseFrame, SLUG_RE, EDIT_TOOLS, ASK_TOOLS };

