"use strict";
// Tiny zero-dependency static file server used for static-site previews.
// Serves <root> under <prefix> (e.g. /preview/<slug>/). Requests that do not
// carry the prefix are served relative to root too (for strip-prefix proxies).

const http = require("http");
const fs = require("fs");
const path = require("path");

const MIME = {
  ".html": "text/html; charset=utf-8",
  ".htm": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".cjs": "text/javascript; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".map": "application/json; charset=utf-8",
  ".txt": "text/plain; charset=utf-8",
  ".md": "text/markdown; charset=utf-8",
  ".xml": "application/xml; charset=utf-8",
  ".svg": "image/svg+xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".webp": "image/webp",
  ".avif": "image/avif",
  ".ico": "image/x-icon",
  ".bmp": "image/bmp",
  ".woff": "font/woff",
  ".woff2": "font/woff2",
  ".ttf": "font/ttf",
  ".otf": "font/otf",
  ".wasm": "application/wasm",
  ".mp4": "video/mp4",
  ".webm": "video/webm",
  ".mp3": "audio/mpeg",
  ".wav": "audio/wav",
  ".ogg": "audio/ogg",
  ".pdf": "application/pdf",
  ".csv": "text/csv; charset=utf-8",
  ".webmanifest": "application/manifest+json",
};

function createStaticServer({ root, prefix, onLog = () => {} }) {
  const rootReal = fs.realpathSync(root);
  const pfx = prefix.endsWith("/") ? prefix : prefix + "/";

  return http.createServer((req, res) => {
    const started = Date.now();
    const done = (status) => onLog(`${req.method} ${req.url} ${status} ${Date.now() - started}ms`);
    if (req.method !== "GET" && req.method !== "HEAD") {
      res.writeHead(405, { Allow: "GET, HEAD" });
      res.end();
      return done(405);
    }
    let pathname;
    try {
      pathname = decodeURIComponent(new URL(req.url, "http://x").pathname);
    } catch {
      res.writeHead(400);
      res.end("Bad request");
      return done(400);
    }
    if (pathname + "/" === pfx) {
      res.writeHead(301, { Location: pfx });
      res.end();
      return done(301);
    }
    let rel = pathname.startsWith(pfx) ? pathname.slice(pfx.length) : pathname.replace(/^\/+/, "");
    if (rel.includes("\0")) {
      res.writeHead(400);
      res.end();
      return done(400);
    }
    let file = path.resolve(rootReal, "." + path.posix.normalize("/" + rel));
    const inside = (p) => p === rootReal || p.startsWith(rootReal + path.sep);
    const send404 = () => {
      res.writeHead(404, { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" });
      res.end("Not found");
      done(404);
    };
    if (!inside(file)) return send404();
    fs.stat(file, (err, st) => {
      if (!err && st.isDirectory()) {
        if (!pathname.endsWith("/")) {
          res.writeHead(301, { Location: pathname + "/" });
          res.end();
          return done(301);
        }
        file = path.join(file, "index.html");
        return serveFile(file);
      }
      if (err) return send404();
      serveFile(file);
    });

    function serveFile(f) {
      fs.realpath(f, (err, real) => {
        if (err || !inside(real)) return send404();
        fs.stat(real, (err2, st) => {
          if (err2 || !st.isFile()) return send404();
          const type = MIME[path.extname(real).toLowerCase()] || "application/octet-stream";
          res.writeHead(200, {
            "Content-Type": type,
            "Content-Length": st.size,
            "Cache-Control": "no-cache",
            "X-Content-Type-Options": "nosniff",
          });
          if (req.method === "HEAD") {
            res.end();
            return done(200);
          }
          const s = fs.createReadStream(real);
          s.on("error", () => res.destroy());
          s.pipe(res);
          res.on("finish", () => done(200));
        });
      });
    }
  });
}

module.exports = { createStaticServer, MIME };

