"use strict";
// Preview process manager: one dev server (or built-in static server) per project.

const { spawn } = require("child_process");
const fs = require("fs");
const net = require("net");
const path = require("path");
const { createStaticServer } = require("./static");

const LOG_LINES = 200;

function probePort(port, timeoutMs = 400) {
  const tryHost = (host) =>
    new Promise((resolve) => {
      const sock = net.connect({ host, port });
      const finish = (ok) => {
        sock.destroy();
        resolve(ok);
      };
      sock.setTimeout(timeoutMs, () => finish(false));
      sock.once("connect", () => finish(true));
      sock.once("error", () => finish(false));
    });
  return tryHost("127.0.0.1").then((ok) => ok || tryHost("::1"));
}

/** Find pids (same uid) with a LISTEN socket on `port`, via /proc. Linux only. */
function listenerPids(port) {
  const inodes = new Set();
  const hex = port.toString(16).toUpperCase().padStart(4, "0");
  for (const f of ["/proc/net/tcp", "/proc/net/tcp6"]) {
    let txt;
    try {
      txt = fs.readFileSync(f, "utf8");
    } catch {
      continue;
    }
    for (const line of txt.split("\n").slice(1)) {
      const cols = line.trim().split(/\s+/);
      if (cols.length < 10) continue;
      const localPort = cols[1].split(":").pop();
      if (localPort === hex && cols[3] === "0A") inodes.add(cols[9]);
    }
  }
  const pids = new Set();
  if (!inodes.size) return [];
  let procs = [];
  try {
    procs = fs.readdirSync("/proc").filter((d) => /^\d+$/.test(d));
  } catch {
    return [];
  }
  for (const pid of procs) {
    let fds;
    try {
      fds = fs.readdirSync(`/proc/${pid}/fd`);
    } catch {
      continue;
    }
    for (const fd of fds) {
      try {
        const l = fs.readlinkSync(`/proc/${pid}/fd/${fd}`);
        const m = /^socket:\[(\d+)\]$/.exec(l);
        if (m && inodes.has(m[1])) {
          pids.add(Number(pid));
          break;
        }
      } catch {
        /* ignore */
      }
    }
  }
  return [...pids];
}

function pgidOf(pid) {
  try {
    const stat = fs.readFileSync(`/proc/${pid}/stat`, "utf8");
    const after = stat.slice(stat.lastIndexOf(")") + 2).split(" ");
    return Number(after[2]); // state ppid pgrp
  } catch {
    return null;
  }
}

function readJSON(file) {
  try {
    return JSON.parse(fs.readFileSync(file, "utf8"));
  } catch {
    return null;
  }
}

/**
 * Decide how to run a project's preview.
 * @returns {{kind:'process', command:string} | {kind:'static', root:string} | {error:string}}
 */
function detectCommand(dir, slug, port) {
  const base = `/preview/${slug}/`;
  const pkg = readJSON(path.join(dir, "package.json"));
  if (pkg) {
    const scripts = pkg.scripts || {};
    const deps = { ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) };
    const install = fs.existsSync(path.join(dir, "node_modules")) ? "" : "npm install --no-audit --no-fund && ";
    if (scripts.dev) {
      if (deps.vite || /\bvite\b/.test(scripts.dev)) {
        return { kind: "process", command: `${install}npm run dev -- --host 0.0.0.0 --port ${port} --strictPort --base ${base}` };
      }
      if (deps.next || /\bnext\b/.test(scripts.dev)) {
        return { kind: "process", command: `${install}npx next dev -p ${port} -H 0.0.0.0` };
      }
      return { kind: "process", command: `${install}npm run dev` };
    }
    if (scripts.start) return { kind: "process", command: `${install}npm start` };
  }
  for (const sub of ["", "dist", "build", "public", "out"]) {
    const root = path.join(dir, sub);
    if (fs.existsSync(path.join(root, "index.html"))) return { kind: "static", root };
  }
  return { error: "Could not detect a preview command (no package.json dev/start script and no index.html). Pass `command`." };
}

class PreviewManager {
  constructor(config) {
    this.config = {
      projectsDir: "/workspace/projects",
      portMin: 4100,
      portMax: 4199,
      env: process.env,
      allowedHost: "claudebox",
      log: () => {},
      ...config,
    };
    this.previews = new Map(); // slug -> record
  }

  _alive(rec) {
    return !!rec && rec.alive;
  }

  _appendLog(rec, text) {
    rec.partial += text;
    const lines = rec.partial.split(/\r?\n/);
    rec.partial = lines.pop();
    for (const l of lines) rec.logs.push(l);
