  const tryHost = (host) =>
    new Promise((resolve) => {
      const sock = net.connect({ host, port });
      const finish = (ok) => {
        sock.destroy();
        resolve(ok);
      };
      sock.setTimeout(timeoutMs, () => finish(false));
      sock.once("connect", () => finish(true));
      sock.once("error", () => finish(false));
    });
