}

/** Find pids (same uid) with a LISTEN socket on `port`, via /proc. Linux only. */
function listenerPids(port) {
  const inodes = new Set();
  const hex = port.toString(16).toUpperCase().padStart(4, "0");
  for (const f of ["/proc/net/tcp", "/proc/net/tcp6"]) {
    let txt;
    try {
      txt = fs.readFileSync(f, "utf8");
    } catch {
      continue;
    }
    for (const line of txt.split("\n").slice(1)) {
      const cols = line.trim().split(/\s+/);
      if (cols.length < 10) continue;
      const localPort = cols[1].split(":").pop();
      if (localPort === hex && cols[3] === "0A") inodes.add(cols[9]);
    }
  }
  const pids = new Set();
  if (!inodes.size) return [];
  let procs = [];
  try {
    procs = fs.readdirSync("/proc").filter((d) => /^\d+$/.test(d));
  } catch {
    return [];
  }
  for (const pid of procs) {
    let fds;
    try {
      fds = fs.readdirSync(`/proc/${pid}/fd`);
    } catch {
      continue;
    }
    for (const fd of fds) {
      try {
        const l = fs.readlinkSync(`/proc/${pid}/fd/${fd}`);
        const m = /^socket:\[(\d+)\]$/.exec(l);
        if (m && inodes.has(m[1])) {
          pids.add(Number(pid));
          break;
        }
      } catch {
        /* ignore */
      }
    }
  }
  return [...pids];
}

