  return new Promise((resolve) => {
    execFile(bin, args, { timeout: timeoutMs, maxBuffer: 4 * 1024 * 1024, env: { ...process.env, CLAUDEBOX_API_KEY: "" } }, (err, stdout, stderr) => {
      resolve({ ok: !err, out: String(stdout || "") + String(stderr || "") });
    });
  });
}

function parseHelpFeatures(help) {
  const features = {};
  const m = /--permission-mode <mode>[\s\S]*?\(choices:\s*([^)]*)\)/.exec(help);
  if (m) features.permissionModes = [...m[1].matchAll(/"([^"]+)"/g)].map((x) => x[1]);
  features.permissionPrompts = /--permission-prompts\b/.test(help);
  features.includePartialMessages = /--include-partial-messages\b/.test(help);
  features.effort = /--effort\b/.test(help);
  return features;
}

async function detectCli() {
  const [ver, help] = await Promise.all([execText(CLAUDE_BIN, ["--version"]), execText(CLAUDE_BIN, ["--help"])]);
  if (ver.ok) cliInfo.version = (ver.out.trim().split(/\s+/)[0] || "").trim() || null;
  if (help.ok || help.out) cliInfo.features = parseHelpFeatures(help.out);
  cliInfo.detected = true;
  log("info", "claude CLI detected", { version: cliInfo.version, features: cliInfo.features });
}

function authMode() {
  if (process.env.CLAUDE_CODE_OAUTH_TOKEN) return "oauth";
  if (process.env.ANTHROPIC_API_KEY) return "api_key";
  const cfgDir = process.env.CLAUDE_CONFIG_DIR || path.join(process.env.HOME || "/home/claude", ".claude");
  try {
    if (fs.statSync(path.join(cfgDir, ".credentials.json")).isFile()) return "credentials";
  } catch {
    /* none */
  }
  return "none";
}

function checkBearer(req) {
  if (!CLAUDEBOX_API_KEY) return ALLOW_NO_AUTH;
  const auth = String(req.headers.authorization || "");
  const expected = `Bearer ${CLAUDEBOX_API_KEY}`;
  const a = Buffer.from(auth);
  const b = Buffer.from(expected);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

async function readJSONBody(req, res, limit = 4 * 1024 * 1024) {
  let size = 0;
  const chunks = [];
  for await (const c of req) {
    size += c.length;
    if (size > limit) {
      sendJSON(res, 413, { error: "Body too large" });
      return undefined;
    }
    chunks.push(c);
  }
  const raw = Buffer.concat(chunks).toString("utf8");
  if (!raw.trim()) return {};
  try {
    return JSON.parse(raw);
  } catch {
    sendJSON(res, 400, { error: "Invalid JSON body" });
    return undefined;
  }
}

