    if (m === "GET" && p === "/v2/previews") return sendJSON(res, 200, { previews: await previews.list() });
    if (m === "GET" && p === "/v2/preview/status") {
      const slug = url.searchParams.get("projectSlug") || "";
      if (!SLUG_RE.test(slug)) return sendJSON(res, 400, { error: "Invalid projectSlug" });
      const port = url.searchParams.get("port") ? parseInt(url.searchParams.get("port"), 10) : undefined;
