        if (port === undefined) return sendJSON(res, 400, { error: "Missing port" });
        const r = await previews.start({ projectSlug: body.projectSlug, port, command: body.command });
        return sendJSON(res, r.status, r.body);
      }
      return sendJSON(res, 200, await previews.stop({ projectSlug: body.projectSlug, port }));
