      await handleV2(req, res, url);
      return;
    }
  } catch (err) {
    log("error", "request failed", { path: url.pathname, error: err.message });
    if (!res.headersSent) sendJSON(res, 500, { error: err.message });
    else res.end();
    return;
  }

  // --- Custom prompt API ---
  if (req.method === "POST" && req.url === "/prompt") {
    if (activeRequests >= MAX_CONCURRENT) {
      log("warn", "rejected request, at capacity", { activeRequests });
      sendJSON(res, 429, { error: "Too many concurrent requests" });
      return;
    }

    activeRequests++;
    try {
      const raw = await readBody(req);
      let body;
      try {
        body = JSON.parse(raw);
      } catch {
        sendJSON(res, 400, { error: "Invalid JSON body" });
        return;
      }

      if (!body.prompt) {
        sendJSON(res, 400, { error: "Missing 'prompt' field" });
        return;
      }

      const result = await runClaude(body.prompt, body.options || {});
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(result);
    } catch (err) {
      sendJSON(res, 500, { error: err.message });
    } finally {
      activeRequests--;
    }
    return;
  }

  // --- OpenAI-compatible endpoints ---
  if (OPENAI_COMPAT) {
    if (req.method === "POST" && req.url === "/v1/chat/completions") {
      await handleChatCompletions(req, res);
      return;
    }

    if (req.method === "GET" && req.url === "/v1/models") {
      handleModels(req, res);
      return;
    }
  }

  // --- 404 ---
  const routes = [
    "POST /prompt",
    "GET /health",
    "POST /v2/run",
    "GET /v2/run/:runId/events",
    "POST /v2/abort",
    "GET /v2/runs",
    "POST /v2/preview/start",
    "POST /v2/preview/stop",
    "GET /v2/preview/status",
  ];
  if (OPENAI_COMPAT) {
    routes.push("POST /v1/chat/completions", "GET /v1/models");
  }
  sendJSON(res, 404, { error: `Not found. Available: ${routes.join(", ")}` });
});

server.keepAliveTimeout = 65000;
server.requestTimeout = 0; // SSE streams are long-lived

async function start(port = PORT, host = "0.0.0.0") {
  await Promise.race([detectCli(), new Promise((r) => setTimeout(r, 20000))]);
  if (!CLAUDEBOX_API_KEY && !ALLOW_NO_AUTH) {
    log("warn", "CLAUDEBOX_API_KEY not set: /v2/* endpoints will reject all requests (set CLAUDEBOX_ALLOW_NO_AUTH=1 to disable auth)");
  }
  await new Promise((resolve) => server.listen(port, host, resolve));
  log("info", `claudebox server listening on port ${server.address().port}`, {
    version: PKG_VERSION,
    claudeVersion: cliInfo.version,
    authMode: authMode(),
    maxConcurrent: MAX_CONCURRENT,
    openaiCompat: OPENAI_COMPAT,
    projectsDir: PROJECTS_DIR,
  });
  return server;
}

function shutdown(sig) {
  log("info", "shutting down", { signal: sig });
  runs.close();
  previews.stopAll().finally(() => process.exit(0));
  setTimeout(() => process.exit(0), 5000).unref();
}

