const AUTH = { Authorization: "Bearer test-key" };

function runMock(prompt) {
  let stdout;
  try {
    stdout = execFileSync(MOCK, ["-p", "--model", "opus", "--", prompt], { encoding: "utf8", env: { ...process.env, MOCK_ARGS_FILE: "" } });
  } catch (e) {
    stdout = e.stdout;
  }
  const events = [];
  const n = new Normalizer((type, data) => events.push({ type, data }));
  n.write(stdout);
  n.finish({ exitCode: 0 });
  return { events, n };
}

const ofType = (evs, t) => evs.filter((e) => e.type === t);
const joinDeltas = (evs, t) => ofType(evs, t).map((e) => e.data.delta).join("");

