test("normalizer: streams thinking/text deltas without duplicating full assistant messages", () => {
  const { events } = runMock("build an app");
  assert.equal(events[0].type, "init");
  assert.equal(events[0].data.sessionId, "11111111-2222-3333-4444-555555555555");
  assert.equal(events[0].data.model, "claude-opus-5-5");
  assert.ok(Array.isArray(events[0].data.tools));
  assert.equal(joinDeltas(events, "thinking"), "Let me plan this out.");
  assert.equal(joinDeltas(events, "text"), "I'll set things up.Done! Server ready.");
  const ends = ofType(events, "block_end").map((e) => e.data.kind);
  assert.deepEqual(ends, ["thinking", "text", "text"]);
  // first event types never include raw CLI types
  for (const e of events) assert.ok(["init", "thinking", "text", "block_end", "tool_use", "tool_result", "todo", "usage", "rate_limit", "result", "error"].includes(e.type), e.type);
});

test("normalizer: tool_use once with full input, tool_result, todo, subagent parentId", () => {
  const { events } = runMock("build an app");
  const uses = ofType(events, "tool_use");
  assert.deepEqual(uses.map((u) => u.data.name), ["TodoWrite", "Bash", "Read"]);
  assert.deepEqual(uses[1].data.input, { command: "npm install", description: "Install dependencies" });
  assert.equal(uses[2].data.parentId, "toolu_bash1");
  const todo = ofType(events, "todo");
