  assert.deepEqual(todo[0].data.todos.map((t) => [t.content, t.status]), [["Install deps", "in_progress"], ["Start server", "pending"]]);
  const results = ofType(events, "tool_result");
  assert.equal(results.length, 2);
  assert.equal(results[1].data.id, "toolu_bash1");
  assert.equal(results[1].data.isError, false);
  assert.match(results[1].data.content, /added 42 packages/);
  assert.equal(ofType(events, "rate_limit")[0].data.rateLimitType, "five_hour");
});

test("normalizer: usage per assistant message (incremental, deduped) and result", () => {
  const { events } = runMock("build an app");
  const usage = ofType(events, "usage");
  const main = usage.filter((u) => !u.data.parentId);
  assert.equal(main.length, 3); // msg_01, msg_02, msg_03
  assert.deepEqual(main[0].data, { inputTokens: 1200, outputTokens: 87, cacheReadTokens: 2000, cacheWriteTokens: 100 });
  const sum = main.reduce((a, u) => a + u.data.outputTokens, 0);
  assert.equal(sum, 87 + 40 + 12);
