test("client disconnect does not kill; reattach + abort kills process group", async () => {
  // Start a slow run and disconnect right after init.
  await sse("POST", "/v2/run", { runId: "run-slow", prompt: "SLOW", projectSlug: "slow" }, (ev, req) => {
    if (ev.type === "init") req.destroy();
  });
  await new Promise((r) => setTimeout(r, 300));
  const list = await request("GET", "/v2/runs");
  const r = list.json.runs.find((x) => x.runId === "run-slow");
  assert.ok(r, "run still listed");
  assert.equal(r.status, "running");
  const pid = r.pid;

  // Reattach from seq 1, abort once replay has delivered init.
  let aborted = false;
  const events = await sse("GET", "/v2/run/run-slow/events?fromSeq=1", undefined, (ev) => {
    if (ev.type === "init" && !aborted) {
      aborted = true;
      request("POST", "/v2/abort", { runId: "run-slow" });
    }
  });
  assert.equal(events[0].type, "init");
  const last = events[events.length - 1];
  assert.equal(last.type, "done");
  assert.equal(last.data.aborted, true);
  assert.equal((await request("GET", "/v2/run/run-slow")).json.status, "aborted");
  assert.throws(() => process.kill(pid, 0));
  assert.equal((await request("POST", "/v2/abort", { runId: "nope" })).status, 404);
});

