function request(method, p, body, headers = AUTH) {
  return new Promise((resolve, reject) => {
    const data = body === undefined ? undefined : JSON.stringify(body);
    const req = http.request(base + p, { method, headers: { ...headers, ...(data ? { "Content-Type": "application/json" } : {}) } }, (res) => {
      let txt = "";
      res.on("data", (c) => (txt += c));
      res.on("end", () => {
        let json = null;
        try {
          json = JSON.parse(txt);
        } catch {
          /* not json */
        }
        resolve({ status: res.statusCode, headers: res.headers, json, text: txt });
      });
    });
    req.on("error", reject);
    if (data) req.write(data);
    req.end();
  });
}

/** Open an SSE stream. onEvent(ev, req) may call req.destroy(). Resolves with events at end. */
function sse(method, p, body, onEvent = () => {}) {
  return new Promise((resolve, reject) => {
    const data = body === undefined ? undefined : JSON.stringify(body);
    const events = [];
    const req = http.request(base + p, { method, headers: { ...AUTH, ...(data ? { "Content-Type": "application/json" } : {}) } }, (res) => {
      if (res.statusCode !== 200) {
        let t = "";
        res.on("data", (c) => (t += c));
        res.on("end", () => reject(new Error(`HTTP ${res.statusCode}: ${t}`)));
        return;
      }
      let buf = "";
      res.setEncoding("utf8");
      res.on("data", (chunk) => {
        buf += chunk;
        let i;
        while ((i = buf.indexOf("\n\n")) !== -1) {
          const frame = buf.slice(0, i);
          buf = buf.slice(i + 2);
          const ev = {};
          for (const line of frame.split("\n")) {
            if (line.startsWith("id: ")) ev.id = Number(line.slice(4));
            else if (line.startsWith("event: ")) ev.type = line.slice(7);
            else if (line.startsWith("data: ")) ev.data = JSON.parse(line.slice(6));
          }
          if (ev.type) {
            events.push(ev);
            onEvent(ev, req);
          }
        }
      });
      res.on("end", () => resolve(events));
      res.on("close", () => resolve(events));
    });
    req.on("error", (e) => (e.code === "ECONNRESET" ? resolve(events) : reject(e)));
    if (data) req.write(data);
    req.end();
  });
}

