  }
  const st = (await request("GET", `/v2/preview/status?projectSlug=ext&port=${port}`)).json;
  assert.equal(st.running, true);
  assert.equal(st.managed, false);
  const stop = await request("POST", "/v2/preview/stop", { projectSlug: "ext", port });
  assert.equal(stop.json.stopped, true);
  await new Promise((r) => setTimeout(r, 300));
  assert.equal((await request("GET", `/v2/preview/status?projectSlug=ext&port=${port}`)).json.listening, false);
  try {
    process.kill(-child.pid, "SIGKILL");
  } catch {
    /* already gone */
  }
});

